#include "rinkfit/joint_shape_cells_v1.hpp"
#include "rinkfit/joint_compact_path_state_v1.hpp"
#include <ceres/manifold.h>
#include <functional>
#include <iostream>
using namespace rinkfit;
static void require(bool v,const char*m){if(!v)throw std::runtime_error(m);}
static void rejects(const std::function<void()>&f,const char*m){bool caught=false;try{f();}catch(const std::exception&){caught=true;}require(caught,m);}
struct Fixture {struct Core{JointEventModel model;JointPacket packet;std::vector<double>station,row,alpha;}core;Fixture(){EventMaterial mat;mat.label="original-static-print";EventPath p;p.kind=6;p.closed=true;p.vertex_blocks={0,1,2,3};mat.paths={p};core.model.materials.push_back(mat);core.model.path_station_intervals[{0,0}]={{0.,1.}};core.packet.rows.resize(2);for(auto&r:core.packet.rows){r.material=0;r.path=0;r.kind=2;r.station=.4;}core.packet.rows[0].active=true;core.packet.rows[0].numerical_shape_segment=1;core.packet.rows[0].source_station_intervals={{.3,.7}};core.packet.rows[0].station_domain_path=0;core.station={.5,-7.};core.row={10.,20.};core.alpha={.1,.2};}};
int main(){try{Fixture b;const auto station=b.core.station,row=b.core.row,alpha=b.core.alpha;const auto old_source_station=b.core.packet.rows[0].station;auto report=initialize_joint_shape_cells_v1(b);require(b.core.packet.rows[0].numerical_shape_segment==1&&b.core.packet.rows[1].numerical_shape_segment==-1,"left side or inactive failure lost during binding");require(station==b.core.station&&row==b.core.row&&alpha==b.core.alpha&&old_source_station==b.core.packet.rows[0].station,"cell binding overwrote original primal/source seed");const auto interval=joint_shape_cell_station_interval_v1(b.core.model,b.core.packet.rows[0],.5);require(interval[0]==.3&&interval[1]==.5,"cell/source interval intersection incorrect");ceres::Problem p;p.AddParameterBlock(&b.core.station[0],1);install_joint_shape_cell_station_bounds_v1(b,p);require(p.GetParameterLowerBound(&b.core.station[0],0)==.3&&p.GetParameterUpperBound(&b.core.station[0],0)==.5,"actual Ceres cell bounds not consumed");p.SetManifold(&b.core.station[0],new ceres::SubsetManifold(1,{}));rejects([&](){install_joint_shape_cell_station_bounds_v1(b,p);},"cross-cell station manifold admitted");
 const auto encoded=joint_shape_cells_RLE_i32_v1(b.core.packet);b.core.packet.rows[0].numerical_shape_segment=2;restore_joint_shape_cells_RLE_i32_v1(encoded,b.core.packet,b.core.model,b.core.station);require(b.core.packet.rows[0].numerical_shape_segment==1,"cold checkpoint lost vertex left/right choice");rejects([&](){restore_joint_shape_cells_RLE_i32_v1("1:0;1:-1;",b.core.packet,b.core.model,b.core.station);},"checkpoint cell outside actual station admitted");require(b.core.packet.rows[0].numerical_shape_segment==1,"invalid checkpoint partially mutated cells");rejects([&](){restore_joint_shape_cells_RLE_i32_v1("2:-1;",b.core.packet,b.core.model,b.core.station);},"missing active local cell admitted");rejects([&](){restore_joint_shape_cells_RLE_i32_v1("1:1;",b.core.packet,b.core.model,b.core.station);},"incomplete raw cell checkpoint admitted");JointCompactPathStateV1 snapshot(b.core.packet);std::uint64_t before=0;snapshot.append_token(before);advance_joint_path_generation_v1(b.core.packet);b.core.packet.rows[0].numerical_shape_segment=2;require(!snapshot.matches(),"accepted state ignored cell-generation change");rejects([&](){snapshot.require_current();},"stale two-vertex graph numerical rollback allowed");rejects([&](){snapshot.adopt_exact_restored_generation(b.core.packet,true);},"wrong restored path snapshot adopted");snapshot.rebind(b.core.packet,true);std::uint64_t after=0;snapshot.append_token(after);require(before!=after,"compact token omitted local cell choice");b.core.packet.rows[0].numerical_shape_segment=1;require(snapshot.matches()&&!snapshot.deep_matches(),"normal owner check unexpectedly scans rows or deep audit missed unregistered write");rejects([&](){snapshot.require_current(true);},"explicit external deep audit missed unregistered write");b.core.packet.rows[0].numerical_shape_segment=2;advance_joint_path_generation_v1(b.core.packet);require(!snapshot.matches()&&snapshot.deep_matches(),"runtime epoch entered mathematical path token");snapshot.adopt_exact_restored_generation(b.core.packet,true);snapshot.require_current();std::uint64_t restored_token=0;snapshot.append_token(restored_token);require(restored_token==after,"runtime epoch changed mathematical compact token");require(joint_shape_segment_from_station_v1(b.core.model.materials[0].paths[0],1.)==3,"closed seam final cell invalid");require(!joint_shape_cell_contains_v1(b.core.model.materials[0].paths[0],0,1.),"fixed cell silently crossed closed seam");advance_joint_path_generation_v1(b.core.packet);b.core.packet.rows[0].numerical_shape_segment=1;rejects([&](){snapshot.rebind_after_local_replacement(b.core.packet,false);},"local snapshot accepted live affected consumers");rejects([&](){snapshot.adopt_exact_restored_local_generation(b.core.packet,true);},"local rollback accepted wrong complete cell state");advance_joint_path_generation_v1(b.core.packet);b.core.packet.rows[0].numerical_shape_segment=2;b.core.packet.rows[1].numerical_shape_segment=0;rejects([&](){snapshot.adopt_exact_restored_local_generation(b.core.packet,true);},"local rollback hid inactive raw cell change");b.core.packet.rows[1].numerical_shape_segment=-1;snapshot.adopt_exact_restored_local_generation(b.core.packet,true);snapshot.require_current();advance_joint_path_generation_v1(b.core.packet);b.core.packet.rows[0].numerical_shape_segment=1;snapshot.rebind_after_local_replacement(b.core.packet,true);snapshot.require_current();std::uint64_t local_token=0;snapshot.append_token(local_token);require(local_token==before,"local replacement used another mathematical path token");std::cout<<"local shape cells: exact source intersection/Ceres bounds, preserved raw failures and left/right cold restore, no stale graph generation passed"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
